    mandatory = models.BooleanField(db_default=False)
    mandatory_for = ArrayField(models.TextField(), db_default=[])
    validity_months = models.SmallIntegerField(blank=True, null=True)
    pass_mark = models.SmallIntegerField(blank=True, null=True)
    active = models.BooleanField(db_default=True)
    created_at = models.DateTimeField(db_default=Now())

    company_scope = 'company'
    objects = CompanyQuerySet.as_manager()

    class Meta:
        db_table = 'lrn_course'
        unique_together = (('company', 'code'),)

    def __str__(self):
        return str(self.title)


